/**
 * Carousel slide builder
 * ------------------------------------------------------------
 * Turns Claude's carousel JSON + a brand kit into one HTML page per slide
 * (1080×1350). Each page is sent to Cloudflare Browser Run /screenshot.
 *
 * n8n usage (Code node, "Run Once for All Items"):
 *   Paste this whole file. The node before it must output ONE item:
 *   { brand: {...brand kit row...}, carousel: {...Claude JSON...}, carouselId: "crs-xxxx" }
 *   Output: one item per slide → { carouselId, lang, n, total, layout, format, html }
 *
 * Browser Run request body (HTTP Request node, Response Format: File):
 *   { html: $json.html,
 *     viewport: { width: 1080, height: 1350 },
 *     gotoOptions: { waitUntil: 'networkidle0' },
 *     waitForSelector: { selector: 'body.ready', timeout: 15000 },
 *     screenshotOptions: $json.format === 'png' ? { type: 'png' } : { type: 'jpeg', quality: 92 } }
 *   body.ready is set after fonts load and long text is shrunk to fit.
 *
 * To swap in the real brand later, change the brand kit row only
 * (colors, fonts, font_css_url, logo_url, handle). No code changes needed.
 */

const DEFAULT_BRAND = {
  brand_name: 'Lajvard',
  handle: '@lajvard.studio',
  logo_url: '', // empty → built-in ring-and-chevron mark
  color_ground: '#1B2A78', // lapis — main dark background
  color_ground_line: '#2A3C9E', // lattice lines + inactive progress on the dark background
  color_tile: '#22A6B3', // turquoise tile
  color_porcelain: '#F2F5FB', // light background / text on dark
  color_gold: '#EBB64A', // single highlight (button, medallion core)
  color_ink: '#101A4F', // text on light background
  color_muted_dark: '#AEB9E6', // secondary text on lapis
  color_muted_light: '#5B6592', // secondary text on porcelain
  font_display: 'Inter',
  font_body: 'Inter',
  font_css_url:
    'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=block',
  output_format: 'jpg',
};

// Small interface strings that are not part of Claude's content.
const UI_STRINGS = {
  'uz-Latn': { swipe: 'Varaqlang' },
  'uz-Cyrl': { swipe: 'Варақланг' },
  ru: { swipe: 'Листайте' },
  en: { swipe: 'Swipe' },
  tr: { swipe: 'Kaydır' },
};

const W = 1080;
const H = 1350;

// ---------- helpers ----------

function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[c]);
}

// Safety net for Uzbek Latin: fix oʻ/gʻ and tutuq belgisi typed with plain apostrophes.
function normalizeText(text, lang) {
  let t = String(text ?? '').trim();
  if (lang === 'uz-Latn') {
    t = t.replace(/([OoGg])['‘’`ʼ]/g, '$1ʻ');
    t = t.replace(/([A-Za-z])['’`]/g, '$1ʼ');
  }
  return t;
}

// ---------- motifs ----------
// A motif supplies exactly 4 decorative functions — medallion/backdrop/
// progress/mark — selected per-carousel via brand.motif_key. It never
// touches headline/body copy layout, and it never draws the brand lockup
// or the site-corner website mark: those are called directly from the
// slide-layout functions below, the same for every motif, so a new motif
// can't accidentally drop the logo or the website by omission.

// "True Bearing" motif — an instrument/calibration-dial visual language
// (concentric rings, a partial tick bezel, a compact two-bar chevron) that
// replaces the old octagram-star family with something built from trading
// infrastructure's own vocabulary (precision, calibration) rather than
// literal chart imagery — chosen over a literal price-chart motif because
// it never visually implies "returns going up", which matters given this
// brand's own compliance rule against implying guaranteed returns.

// Badge: two concentric rings, a partial tick bezel (only at large size),
// and a small solid chevron at the center. Same function at two scales —
// the ~460px cover badge gets the full tick bezel; the ~240px CTA badge
// drops the bezel and inner ring so it stays crisp instead of turning to
// noise at small scale.
function instrumentMedallion(b, size) {
  const c = size / 2;
  const outerR = size * 0.46;
  const innerR = size * 0.34;
  const full = size >= 400;
  let svg = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true">`;
  svg += `<circle cx="${c}" cy="${c}" r="${outerR.toFixed(1)}" fill="none" stroke="${b.color_gold}" stroke-width="1.5"/>`;
  if (full) {
    svg += `<circle cx="${c}" cy="${c}" r="${innerR.toFixed(1)}" fill="none" stroke="${b.color_gold}" stroke-width="1" opacity="0.5"/>`;
    // 7 tick bars over a 240° arc, leaving a deliberate 120° gap toward the
    // lower-right — the asymmetry reads as a calibrated dial, not a sunburst.
    const tickCount = 7;
    const arcSpan = 240;
    const gapCenter = 135;
    const startAngle = gapCenter + (360 - arcSpan) / 2;
    const step = arcSpan / (tickCount - 1);
    for (let i = 0; i < tickCount; i++) {
      const angleDeg = startAngle + i * step;
      const a = ((angleDeg - 90) * Math.PI) / 180;
      const tx = c + outerR * Math.cos(a);
      const ty = c + outerR * Math.sin(a);
      svg += `<rect x="${(tx - 1).toFixed(1)}" y="${(ty - 7).toFixed(1)}" width="2" height="14" rx="1" fill="${b.color_gold}" opacity="0.7" transform="rotate(${angleDeg.toFixed(1)} ${tx.toFixed(1)} ${ty.toFixed(1)})"/>`;
    }
  }
  const barLen = size * 0.048;
  const barW = Math.max(2, size * 0.0065);
  const bx = (c - barW / 2).toFixed(1);
  const by = (c - barLen / 2).toFixed(1);
  svg += `<rect x="${bx}" y="${by}" width="${barW.toFixed(1)}" height="${barLen.toFixed(1)}" rx="${(barW / 2).toFixed(1)}" fill="${b.color_gold}" transform="rotate(18 ${c} ${c})"/>`;
  svg += `<rect x="${bx}" y="${by}" width="${barW.toFixed(1)}" height="${barLen.toFixed(1)}" rx="${(barW / 2).toFixed(1)}" fill="${b.color_gold}" transform="rotate(-18 ${c} ${c})"/>`;
  svg += `</svg>`;
  return svg;
}

function instrumentMark(b) {
  if (b.logo_url) {
    return `<img class="logo-img" src="${esc(b.logo_url)}" alt="">`;
  }
  return `<svg class="mark" viewBox="0 0 48 48" aria-hidden="true">
    <circle cx="24" cy="24" r="21" fill="none" stroke="${b.color_gold}" stroke-width="2"/>
    <rect x="22.5" y="13" width="3" height="14" rx="1.5" fill="${b.color_gold}" transform="rotate(18 24 24)"/>
    <rect x="22.5" y="13" width="3" height="14" rx="1.5" fill="${b.color_gold}" transform="rotate(-18 24 24)"/>
  </svg>`;
}

// The brand lockup always uses the logo image when brand.logo_url is set
// (true in production), regardless of motif — motif.mark only supplies the
// no-logo fallback icon, so a new motif's "mark" is rarely even seen live.
function lockup(b, motif) {
  return `<div class="lockup">${motif.mark(b)}<span>${esc(b.brand_name)}</span></div>`;
}

// Full-bleed background: a barely-visible dot lattice (ambient texture, not
// a border), two vertical hairlines tucked safely inside the outer margin,
// and small "+" registration ticks in the four corners. Everything uses
// currentColor so one markup adapts to both dark and light slides — no
// per-brand color wiring needed. The lines sit at x=60/x=1020, inside the
// 88px slide padding, specifically so they never cross centered CTA text or
// wrap under a headline the way a center line would.
function instrumentBackdrop(b) {
  const corners = [[60, 60], [W - 60, 60], [60, H - 60], [W - 60, H - 60]];
  const ticks = corners
    .map(
      ([x, y]) => `<line x1="${x - 5}" y1="${y}" x2="${x + 5}" y2="${y}" stroke="currentColor" stroke-width="1" opacity="0.1"/>
    <line x1="${x}" y1="${y - 5}" x2="${x}" y2="${y + 5}" stroke="currentColor" stroke-width="1" opacity="0.1"/>`
    )
    .join('\n    ');
  return `<svg class="pattern" width="${W}" height="${H}" aria-hidden="true">
    <defs><pattern id="dots" width="90" height="156" patternUnits="userSpaceOnUse">
      <circle cx="0" cy="0" r="1" fill="currentColor" opacity="0.05"/>
      <circle cx="90" cy="0" r="1" fill="currentColor" opacity="0.05"/>
      <circle cx="45" cy="78" r="1" fill="currentColor" opacity="0.05"/>
    </pattern></defs>
    <rect width="${W}" height="${H}" fill="url(#dots)"/>
    <line x1="60" y1="0" x2="60" y2="${H}" stroke="currentColor" stroke-width="1" opacity="0.08"/>
    <line x1="${W - 60}" y1="0" x2="${W - 60}" y2="${H}" stroke="currentColor" stroke-width="1" opacity="0.08"/>
    ${ticks}
  </svg>`;
}

// Progress dots reuse the medallion's own ring-vs-fill language: an inactive
// slide is a hollow gold ring, the current slide is a solid gold dot with a
// wider ring around it — a miniature echo of the badge, not a separate motif.
function instrumentProgress(b, n, total) {
  let out = '';
  for (let i = 1; i <= total; i++) {
    out +=
      i === n
        ? `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3" fill="${b.color_gold}"/><circle cx="12" cy="12" r="6" fill="none" stroke="${b.color_gold}" stroke-width="1"/></svg>`
        : `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3" fill="none" stroke="${b.color_gold}" stroke-width="1.5" opacity="0.35"/></svg>`;
  }
  return `<div class="progress" aria-label="${n} / ${total}">${out}</div>`;
}

// "Double Tick" motif — a line-art reinterpretation of chat bubbles and
// read-receipt double-ticks for the Sarcastic/Memes template. The joke is a
// design pun, not a punchline graphic: the medallion's focal icon is a
// read-receipt mark ("you already know this, right?" = you've already
// "seen" it), and progress dots quietly read as seen-vs-unread bubbles.
// Deliberately built from zero chart/candlestick/growth shapes (that lesson
// was already learned designing the Informative template's motif) and zero
// checkmark/certification/notification-badge shapes — a design-workflow
// judge panel flagged both as compliance-adjacent (implied verification,
// implied urgency) and those exact devices were dropped before this shipped:
// the medallion carries no notification dot, and the "tick" glyph is two
// independent parallel dashes with no bend, so it can never read as a ✓.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Rounded square with a small triangular tail on one corner — an abstract
// chat-bubble silhouette, never literally drawn as app UI.
function bubbleGlyph(cx, cy, size, rotation, stroke, strokeWidth, opacity, filled) {
  const r = size / 2;
  const corner = size * 0.18;
  const tail = size * 0.22;
  const fillAttr = filled ? stroke : 'none';
  return `<g transform="rotate(${rotation.toFixed(1)} ${cx.toFixed(1)} ${cy.toFixed(1)})" opacity="${opacity}">
    <rect x="${(cx - r).toFixed(1)}" y="${(cy - r).toFixed(1)}" width="${size.toFixed(1)}" height="${size.toFixed(1)}" rx="${corner.toFixed(1)}" fill="${fillAttr}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}"/>
    <path d="M ${(cx + r - tail * 0.7).toFixed(1)} ${(cy + r).toFixed(1)} L ${(cx + r + tail * 0.5).toFixed(1)} ${(cy + r + tail * 0.6).toFixed(1)} L ${(cx + r).toFixed(1)} ${(cy + r - tail * 0.2).toFixed(1)}" fill="${fillAttr}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}" stroke-linecap="round" stroke-linejoin="round"/>
  </g>`;
}

// Two short parallel diagonal dashes, offset — a read-receipt "tick" mark
// with no bend anywhere, so it never converges into a checkmark silhouette.
function tickGlyph(cx, cy, size, rotation, stroke, strokeWidth, opacity) {
  const dx = size * 0.22;
  const dy = size * 0.3;
  const gap = size * 0.3;
  return `<g transform="rotate(${rotation.toFixed(1)} ${cx.toFixed(1)} ${cy.toFixed(1)})" opacity="${opacity}">
    <line x1="${(cx - gap / 2 - dx / 2).toFixed(1)}" y1="${(cy - dy / 2).toFixed(1)}" x2="${(cx - gap / 2 + dx / 2).toFixed(1)}" y2="${(cy + dy / 2).toFixed(1)}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}" stroke-linecap="round"/>
    <line x1="${(cx + gap / 2 - dx / 2).toFixed(1)}" y1="${(cy - dy / 2).toFixed(1)}" x2="${(cx + gap / 2 + dx / 2).toFixed(1)}" y2="${(cy + dy / 2).toFixed(1)}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}" stroke-linecap="round"/>
  </g>`;
}

function dotsGlyph(cx, cy, size, stroke, opacity) {
  const r = size * 0.09;
  const gap = size * 0.32;
  let out = '';
  for (let i = -1; i <= 1; i++) {
    out += `<circle cx="${(cx + i * gap).toFixed(1)}" cy="${cy.toFixed(1)}" r="${r.toFixed(1)}" fill="${stroke}" opacity="${opacity}"/>`;
  }
  return out;
}

// Badge: two concentric notch-bubble squares (the inner one rotated ~9°, a
// quiet "stack of overlapping bubbles" cue), with the tick glyph centered as
// the bold focal icon — literally a read-receipt mark as the emblem. No
// notification dot (dropped: an unread-count badge is an urgency device the
// brand voice rules forbid, regardless of color).
function memeMedallion(b, size) {
  const c = size / 2;
  const outerSize = size * 0.86;
  const innerSize = outerSize * 0.78;
  let svg = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true">`;
  svg += bubbleGlyph(c, c, outerSize, 0, b.color_gold, size * 0.0065, 1, false);
  svg += bubbleGlyph(c, c, innerSize, 9, b.color_gold, size * 0.0045, 0.6, false);
  svg += tickGlyph(c, c, size * 0.42, 0, b.color_gold, size * 0.03, 1);
  svg += `</svg>`;
  return svg;
}

function memeMark(b) {
  if (b.logo_url) {
    return `<img class="logo-img" src="${esc(b.logo_url)}" alt="">`;
  }
  return `<svg class="mark" viewBox="0 0 48 48" aria-hidden="true">${bubbleGlyph(24, 24, 34, 0, b.color_gold, 2.4, 1, false)}${tickGlyph(24, 24, 16, 0, b.color_gold, 2.6, 1)}</svg>`;
}

// Full-bleed scatter of 3 glyphs from one shared shape family (bubbles,
// ticks, a typing-dots triad) — deterministically seeded so every render is
// identical, not visual noise. A central zone stays clear of glyphs, and
// every instance sits at 6-8% opacity, so the pattern never competes with
// headline/body text even where it does cross behind it.
function memeBackdrop(b) {
  const rand = mulberry32(20260917);
  // Text can plausibly sit anywhere in this zone across all 3 slide types
  // (cover's bottom-anchored title, content's/cta's centered blocks) — kept
  // fully clear of bubble/tick glyphs, not just biased, after an earlier
  // render showed a "biased density" approach still crowded real text.
  const safe = { x0: 120, y0: 230, x1: 960, y1: 1150 };
  const glyphs = [];
  let guard = 0;
  while (glyphs.length < 16 && guard++ < 500) {
    const x = 40 + rand() * (W - 80);
    const y = 40 + rand() * (H - 80);
    if (x > safe.x0 && x < safe.x1 && y > safe.y0 && y < safe.y1) continue;
    const size = 26 + rand() * 30;
    const rotation = (rand() - 0.5) * 40;
    const roll = rand();
    const kind = roll < 0.5 ? 'bubble' : roll < 0.8 ? 'tick' : 'dots';
    const isGold = rand() < 0.3;
    const stroke = isGold ? b.color_gold : 'currentColor';
    const opacity = isGold ? 0.05 : 0.06;
    glyphs.push({ x, y, size, rotation, kind, stroke, opacity });
  }
  // The typing-dots triad is small enough (like True Bearing's dot lattice)
  // to read as ambient texture rather than a shape, so it alone is allowed
  // to scatter across the full canvas, still at very low opacity.
  const dotCount = 10;
  for (let i = 0; i < dotCount; i++) {
    glyphs.push({
      x: 40 + rand() * (W - 80),
      y: 40 + rand() * (H - 80),
      size: 14 + rand() * 10,
      rotation: 0,
      kind: 'dots',
      stroke: 'currentColor',
      opacity: 0.05,
    });
  }
  const body = glyphs
    .map((g) => {
      const sw = Math.max(1, g.size * 0.05);
      if (g.kind === 'bubble') return bubbleGlyph(g.x, g.y, g.size, g.rotation, g.stroke, sw, g.opacity, false);
      if (g.kind === 'tick') return tickGlyph(g.x, g.y, g.size, g.rotation, g.stroke, sw, g.opacity);
      return dotsGlyph(g.x, g.y, g.size * 0.6, g.stroke, g.opacity);
    })
    .join('');
  return `<svg class="pattern" width="${W}" height="${H}" aria-hidden="true">${body}</svg>`;
}

// Progress dots stay on the same bubble shape as the rest of the system:
// inactive is a hollow outline, passed is a dim filled bubble ("delivered
// but already scrolled past"), active is a bold gold filled bubble.
function memeProgress(b, n, total) {
  let out = '';
  for (let i = 1; i <= total; i++) {
    if (i === n) {
      out += `<svg viewBox="0 0 24 24" aria-hidden="true">${bubbleGlyph(12, 12, 15, 0, b.color_gold, 1, 1, true)}</svg>`;
    } else if (i < n) {
      out += `<svg viewBox="0 0 24 24" aria-hidden="true">${bubbleGlyph(12, 12, 11, 0, b.color_muted_light, 1, 0.55, true)}</svg>`;
    } else {
      out += `<svg viewBox="0 0 24 24" aria-hidden="true">${bubbleGlyph(12, 12, 11, 0, b.color_muted_light, 1.3, 0.35, false)}</svg>`;
    }
  }
  return `<div class="progress" aria-label="${n} / ${total}">${out}</div>`;
}

// ---------- motif registry ----------
// Each pack supplies medallion/backdrop/progress/mark. cssVars lets a motif
// nudge shared typographic feel (e.g. a bolder headline weight) without any
// of the 3 slide-layout functions changing — empty by default.
const MOTIFS = {
  instrument: {
    medallion: instrumentMedallion,
    backdrop: instrumentBackdrop,
    progress: instrumentProgress,
    mark: instrumentMark,
    cssVars: {},
  },
  meme: {
    medallion: memeMedallion,
    backdrop: memeBackdrop,
    progress: memeProgress,
    mark: memeMark,
    cssVars: {},
  },
};

function resolveMotif(b) {
  return MOTIFS[b.motif_key] || MOTIFS.instrument;
}

// Shrinks any [data-fit] element until its text fits its max-height.
// Adds body.ready when done → can be used with Browser Run's waitForSelector.
const FIT_SCRIPT = `
(function () {
  var done = false;
  function fit() {
    if (done) return; done = true;
    document.querySelectorAll('[data-fit]').forEach(function (el) {
      var cs = getComputedStyle(el);
      var min = parseFloat(el.dataset.min) || 28;
      var maxH = parseFloat(cs.maxHeight);
      var size = parseFloat(cs.fontSize);
      var guard = 0;
      el.style.maxHeight = 'none';
      // offsetHeight = height of the line boxes (ignores glyph ink overflow)
      while (el.offsetHeight > maxH + 1 && size > min && guard++ < 80) {
        size -= 2;
        el.style.fontSize = size + 'px';
      }
    });
    document.body.classList.add('ready');
  }
  var b = document.body.dataset;
  var sample = document.body.innerText;
  if (document.fonts && document.fonts.load) {
    Promise.all([
      document.fonts.load('600 80px "' + b.display + '"', sample),
      document.fonts.load('400 40px "' + b.body + '"', sample),
      document.fonts.load('600 40px "' + b.body + '"', sample)
    ]).then(function () { return document.fonts.ready; }).then(fit, fit);
  }
  setTimeout(fit, 5000);
})();`;

function css(b) {
  return `
:root {
  --ground: ${b.color_ground}; --tile: ${b.color_tile}; --porcelain: ${b.color_porcelain};
  --gold: ${b.color_gold}; --ink: ${b.color_ink};
  --muted-dark: ${b.color_muted_dark}; --muted-light: ${b.color_muted_light};
  --display: '${b.font_display}', 'Segoe UI', Arial, sans-serif;
  --body: '${b.font_body}', 'Segoe UI', Arial, sans-serif;
  --headline-weight: 600; --headline-tracking: -0.012em;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: ${W}px; height: ${H}px; overflow: hidden; }
body { font-family: var(--body); -webkit-font-smoothing: antialiased; overflow-wrap: break-word; }
.slide { position: relative; width: ${W}px; height: ${H}px; overflow: hidden;
  padding: 88px; display: flex; flex-direction: column; }
.dark { background: var(--ground); color: var(--porcelain); }
.light { background: var(--porcelain); color: var(--ink); }
.pattern { position: absolute; left: 0; top: 0; z-index: 0; }
.layer { position: relative; z-index: 1; }

.lockup { display: flex; align-items: center; gap: 16px;
  font-family: var(--display); font-weight: 600; font-size: 38px; letter-spacing: 0.01em; }
.mark, .logo-img { width: 48px; height: 48px; object-fit: contain; }

.brand-top { display: flex; justify-content: center; }
.site-corner { position: absolute; top: 88px; left: 88px; font-size: 26px; font-weight: 500;
  opacity: 0.55; z-index: 1; }

.headline { font-family: var(--display); font-weight: var(--headline-weight); line-height: 1.06;
  letter-spacing: var(--headline-tracking); text-wrap: balance; }
.lede { font-weight: 400; line-height: 1.32; text-wrap: pretty; }
.copy { font-weight: 400; line-height: 1.42; text-wrap: pretty; }

.progress { display: flex; gap: 10px; align-items: center; }
.progress svg { width: 22px; height: 22px; }

/* cover */
.cover .medallion { position: absolute; right: -60px; top: 96px; z-index: 1; }
.cover-text { margin-top: auto; }
.cover-title { font-size: 96px; max-height: 420px; }
.cover-sub { font-size: 36px; max-height: 108px; margin-top: 34px; color: var(--muted-dark); }
.foot { display: flex; justify-content: space-between; align-items: center; margin-top: 64px; }
.swipe { font-size: 30px; font-weight: 500; color: var(--muted-dark); }

/* content */
.content-main { flex: 1; display: flex; flex-direction: column; justify-content: center;
  padding-bottom: 120px; }
.content-title { font-size: 72px; max-height: 260px; }
.content-rule { width: 96px; height: 6px; background: var(--tile); margin: 48px 0 40px; }
.content-body { font-size: 36px; max-height: 460px; color: var(--muted-light); }

/* cta */
.cta-main { flex: 1; display: flex; flex-direction: column; align-items: center;
  justify-content: center; text-align: center; }
.cta-title { font-size: 72px; max-height: 280px; margin-top: 56px; }
.cta-sub { font-size: 36px; max-height: 104px; margin-top: 28px; color: var(--muted-dark); max-width: 820px; }
.button { margin-top: 56px; background: var(--gold); color: var(--ink); font-weight: 600;
  font-size: 40px; line-height: 1; padding: 30px 56px; border-radius: 999px; max-width: 820px; }
.handle { margin-top: 30px; font-size: 32px; font-weight: 500; color: var(--muted-dark); }
.cta .foot { justify-content: center; }
`;
}

function page(b, lang, bodyHtml, fontCss, motifCssVars) {
  const fonts = fontCss
    ? `<style>${fontCss}</style>`
    : `<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="${esc(b.font_css_url)}">`;
  const overrideEntries = Object.entries(motifCssVars || {});
  const motifOverride = overrideEntries.length
    ? `<style>:root{${overrideEntries.map(([k, v]) => `${k}:${v};`).join('')}}</style>`
    : '';
  return `<!doctype html>
<html lang="${esc(lang)}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=${W}, height=${H}">
${fonts}
<style>${css(b)}</style>
${motifOverride}
</head>
<body data-display="${esc(b.font_display)}" data-body="${esc(b.font_body)}">
${bodyHtml}
<script>${FIT_SCRIPT}</script>
</body>
</html>`;
}

// ---------- layouts ----------

function coverSlide(b, s, lang, total, motif) {
  const ui = UI_STRINGS[lang] || UI_STRINGS.en;
  return `<main class="slide dark cover">
  ${motif.backdrop(b)}
  <div class="medallion">${motif.medallion(b, 460)}</div>
  <div class="layer brand-top">${lockup(b, motif)}</div>
  <p class="site-corner">${esc(b.handle)}</p>
  <div class="layer cover-text">
    <h1 class="headline cover-title" data-fit data-min="56">${esc(s.title)}</h1>
    ${s.subtitle ? `<p class="lede cover-sub" data-fit data-min="28">${esc(s.subtitle)}</p>` : ''}
  </div>
  <div class="layer foot">${motif.progress(b, s.n, total)}<span class="swipe">${esc(ui.swipe)}</span></div>
</main>`;
}

function contentSlide(b, s, lang, total, motif) {
  return `<main class="slide light content">
  ${motif.backdrop(b)}
  <div class="layer brand-top">${lockup(b, motif)}</div>
  <p class="site-corner">${esc(b.handle)}</p>
  <div class="layer content-main">
    <h2 class="headline content-title" data-fit data-min="48">${esc(s.title)}</h2>
    <div class="content-rule"></div>
    ${s.body ? `<p class="copy content-body" data-fit data-min="30">${esc(s.body)}</p>` : ''}
  </div>
  <div class="layer foot">${motif.progress(b, s.n, total)}</div>
</main>`;
}

function ctaSlide(b, s, lang, total, motif) {
  return `<main class="slide dark cta">
  ${motif.backdrop(b)}
  <div class="layer brand-top">${lockup(b, motif)}</div>
  <p class="site-corner">${esc(b.handle)}</p>
  <div class="layer cta-main">
    ${motif.medallion(b, 240)}
    <h2 class="headline cta-title" data-fit data-min="52">${esc(s.title)}</h2>
    ${s.subtitle ? `<p class="lede cta-sub" data-fit data-min="28">${esc(s.subtitle)}</p>` : ''}
    ${s.button ? `<div class="button">${esc(s.button)}</div>` : ''}
    <p class="handle">${esc(b.handle)}</p>
  </div>
  <div class="layer foot">${motif.progress(b, s.n, total)}</div>
</main>`;
}

const LAYOUTS = { cover: coverSlide, content: contentSlide, cta: ctaSlide };

/**
 * Build HTML for every slide in a carousel.
 * @returns {Array<{n, total, layout, lang, html}>}
 */
function buildCarousel(brandInput, carousel, opts = {}) {
  const b = { ...DEFAULT_BRAND, ...(brandInput || {}) };
  const motif = resolveMotif(b);
  const lang = carousel.language || 'uz-Latn';
  const slides = [...(carousel.slides || [])].sort((a, z) => a.n - z.n);
  const total = slides.length;
  return slides.map((raw, i) => {
    const s = {
      n: raw.n ?? i + 1,
      layout: raw.layout,
      title: normalizeText(raw.title, lang),
      subtitle: normalizeText(raw.subtitle, lang),
      body: normalizeText(raw.body, lang),
      button: normalizeText(raw.button, lang),
    };
    const layout = LAYOUTS[s.layout] || (i === 0 ? coverSlide : i === total - 1 ? ctaSlide : contentSlide);
    return {
      n: s.n,
      total,
      layout: s.layout,
      lang,
      html: page(b, lang, layout(b, s, lang, total, motif), opts.fontCss, motif.cssVars),
    };
  });
}

// ---------- n8n entry ----------
if (typeof $input !== 'undefined') {
  const src = $input.first().json;
  const brand = src.brand || {};
  const carousel = src.carousel || src.output || src;
  const carouselId = src.carouselId || `crs-${Date.now().toString(36)}`;
  const format = (brand.output_format || carousel.output_format || 'jpg').toLowerCase() === 'png' ? 'png' : 'jpg';
  return buildCarousel(brand, carousel).map((s) => ({
    json: { carouselId, lang: s.lang, n: s.n, total: s.total, layout: s.layout, format, html: s.html },
  }));
}

// ---------- local usage (Node) ----------
if (typeof module !== 'undefined') {
  module.exports = { buildCarousel, DEFAULT_BRAND, UI_STRINGS, MOTIFS };
}

/**
 * Name Files — n8n Code node ("Run Once for Each Item")
 * ------------------------------------------------------------
 * Place right after the "Render Slide" HTTP Request node (Response Format: File).
 * Browser Run returns the image without a filename; Telegram would show "file".
 * This gives each slide a sortable name and the right MIME type, and keeps the
 * slide metadata from the "Build Slides" node (without the large html string).
 *
 * Output: { json: { carouselId, lang, n, total, layout, format, fileName }, binary: { data } }
 */

const { html, ...meta } = $('Build Slides').item.json;
const ext = meta.format === 'png' ? 'png' : 'jpg';
const nn = String(meta.n).padStart(2, '0');

const bin = $input.item.binary && $input.item.binary.data;
if (!bin) {
  throw new Error(`Slide ${meta.n} (${meta.lang}): no image returned by Render Slide`);
}

bin.fileName = `${meta.carouselId}_${meta.lang}_${nn}.${ext}`;
bin.mimeType = ext === 'png' ? 'image/png' : 'image/jpeg';
bin.fileExtension = ext;

return { json: { ...meta, fileName: bin.fileName }, binary: { data: bin } };

/**
 * Carousel slide builder
 * ------------------------------------------------------------
 * Turns Claude's carousel JSON + a brand kit into one HTML page per slide
 * (1080×1350). Each page is sent to Cloudflare Browser Run /screenshot.
 *
 * n8n usage (Code node, "Run Once for All Items"):
 *   Paste this whole file. The node before it must output ONE item:
 *   { brand: {...brand kit row...}, carousel: {...Claude JSON...}, carouselId: "crs-xxxx" }
 *   Output: one item per slide → { carouselId, lang, n, total, layout, format, html }
 *
 * Browser Run request body (HTTP Request node, Response Format: File):
 *   { html: $json.html,
 *     viewport: { width: 1080, height: 1350 },
 *     gotoOptions: { waitUntil: 'networkidle0' },
 *     waitForSelector: { selector: 'body.ready', timeout: 15000 },
 *     screenshotOptions: $json.format === 'png' ? { type: 'png' } : { type: 'jpeg', quality: 92 } }
 *   body.ready is set after fonts load and long text is shrunk to fit.
 *
 * To swap in the real brand later, change the brand kit row only
 * (colors, fonts, font_css_url, logo_url, handle). No code changes needed.
 */

const DEFAULT_BRAND = {
  brand_name: 'Lajvard',
  handle: '@lajvard.studio',
  logo_url: '', // empty → built-in ring-and-chevron mark
  color_ground: '#1B2A78', // lapis — main dark background
  color_ground_line: '#2A3C9E', // lattice lines + inactive progress on the dark background
  color_tile: '#22A6B3', // turquoise tile
  color_porcelain: '#F2F5FB', // light background / text on dark
  color_gold: '#EBB64A', // single highlight (button, medallion core)
  color_ink: '#101A4F', // text on light background
  color_muted_dark: '#AEB9E6', // secondary text on lapis
  color_muted_light: '#5B6592', // secondary text on porcelain
  font_display: 'Inter',
  font_body: 'Inter',
  font_css_url:
    'https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=block',
  output_format: 'jpg',
};

// Small interface strings that are not part of Claude's content.
const UI_STRINGS = {
  'uz-Latn': { swipe: 'Varaqlang' },
  'uz-Cyrl': { swipe: 'Варақланг' },
  ru: { swipe: 'Листайте' },
  en: { swipe: 'Swipe' },
  tr: { swipe: 'Kaydır' },
};

const W = 1080;
const H = 1350;

// ---------- helpers ----------

function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[c]);
}

// Safety net for Uzbek Latin: fix oʻ/gʻ and tutuq belgisi typed with plain apostrophes.
function normalizeText(text, lang) {
  let t = String(text ?? '').trim();
  if (lang === 'uz-Latn') {
    t = t.replace(/([OoGg])['‘’`ʼ]/g, '$1ʻ');
    t = t.replace(/([A-Za-z])['’`]/g, '$1ʼ');
  }
  return t;
}

// ---------- motifs ----------
// A motif supplies exactly 4 decorative functions — medallion/backdrop/
// progress/mark — selected per-carousel via brand.motif_key. It never
// touches headline/body copy layout, and it never draws the brand lockup
// or the site-corner website mark: those are called directly from the
// slide-layout functions below, the same for every motif, so a new motif
// can't accidentally drop the logo or the website by omission.

// "True Bearing" motif — an instrument/calibration-dial visual language
// (concentric rings, a partial tick bezel, a compact two-bar chevron) that
// replaces the old octagram-star family with something built from trading
// infrastructure's own vocabulary (precision, calibration) rather than
// literal chart imagery — chosen over a literal price-chart motif because
// it never visually implies "returns going up", which matters given this
// brand's own compliance rule against implying guaranteed returns.

// Badge: two concentric rings, a partial tick bezel (only at large size),
// and a small solid chevron at the center. Same function at two scales —
// the ~460px cover badge gets the full tick bezel; the ~240px CTA badge
// drops the bezel and inner ring so it stays crisp instead of turning to
// noise at small scale.
function instrumentMedallion(b, size) {
  const c = size / 2;
  const outerR = size * 0.46;
  const innerR = size * 0.34;
  const full = size >= 400;
  let svg = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true">`;
  svg += `<circle cx="${c}" cy="${c}" r="${outerR.toFixed(1)}" fill="none" stroke="${b.color_gold}" stroke-width="1.5"/>`;
  if (full) {
    svg += `<circle cx="${c}" cy="${c}" r="${innerR.toFixed(1)}" fill="none" stroke="${b.color_gold}" stroke-width="1" opacity="0.5"/>`;
    // 7 tick bars over a 240° arc, leaving a deliberate 120° gap toward the
    // lower-right — the asymmetry reads as a calibrated dial, not a sunburst.
    const tickCount = 7;
    const arcSpan = 240;
    const gapCenter = 135;
    const startAngle = gapCenter + (360 - arcSpan) / 2;
    const step = arcSpan / (tickCount - 1);
    for (let i = 0; i < tickCount; i++) {
      const angleDeg = startAngle + i * step;
      const a = ((angleDeg - 90) * Math.PI) / 180;
      const tx = c + outerR * Math.cos(a);
      const ty = c + outerR * Math.sin(a);
      svg += `<rect x="${(tx - 1).toFixed(1)}" y="${(ty - 7).toFixed(1)}" width="2" height="14" rx="1" fill="${b.color_gold}" opacity="0.7" transform="rotate(${angleDeg.toFixed(1)} ${tx.toFixed(1)} ${ty.toFixed(1)})"/>`;
    }
  }
  const barLen = size * 0.048;
  const barW = Math.max(2, size * 0.0065);
  const bx = (c - barW / 2).toFixed(1);
  const by = (c - barLen / 2).toFixed(1);
  svg += `<rect x="${bx}" y="${by}" width="${barW.toFixed(1)}" height="${barLen.toFixed(1)}" rx="${(barW / 2).toFixed(1)}" fill="${b.color_gold}" transform="rotate(18 ${c} ${c})"/>`;
  svg += `<rect x="${bx}" y="${by}" width="${barW.toFixed(1)}" height="${barLen.toFixed(1)}" rx="${(barW / 2).toFixed(1)}" fill="${b.color_gold}" transform="rotate(-18 ${c} ${c})"/>`;
  svg += `</svg>`;
  return svg;
}

function instrumentMark(b) {
  if (b.logo_url) {
    return `<img class="logo-img" src="${esc(b.logo_url)}" alt="">`;
  }
  return `<svg class="mark" viewBox="0 0 48 48" aria-hidden="true">
    <circle cx="24" cy="24" r="21" fill="none" stroke="${b.color_gold}" stroke-width="2"/>
    <rect x="22.5" y="13" width="3" height="14" rx="1.5" fill="${b.color_gold}" transform="rotate(18 24 24)"/>
    <rect x="22.5" y="13" width="3" height="14" rx="1.5" fill="${b.color_gold}" transform="rotate(-18 24 24)"/>
  </svg>`;
}

// The brand lockup always uses the logo image when brand.logo_url is set
// (true in production), regardless of motif — motif.mark only supplies the
// no-logo fallback icon, so a new motif's "mark" is rarely even seen live.
function lockup(b, motif) {
  return `<div class="lockup">${motif.mark(b)}<span>${esc(b.brand_name)}</span></div>`;
}

// Full-bleed background: a barely-visible dot lattice (ambient texture, not
// a border), two vertical hairlines tucked safely inside the outer margin,
// and small "+" registration ticks in the four corners. Everything uses
// currentColor so one markup adapts to both dark and light slides — no
// per-brand color wiring needed. The lines sit at x=60/x=1020, inside the
// 88px slide padding, specifically so they never cross centered CTA text or
// wrap under a headline the way a center line would.
function instrumentBackdrop(b) {
  const corners = [[60, 60], [W - 60, 60], [60, H - 60], [W - 60, H - 60]];
  const ticks = corners
    .map(
      ([x, y]) => `<line x1="${x - 5}" y1="${y}" x2="${x + 5}" y2="${y}" stroke="currentColor" stroke-width="1" opacity="0.1"/>
    <line x1="${x}" y1="${y - 5}" x2="${x}" y2="${y + 5}" stroke="currentColor" stroke-width="1" opacity="0.1"/>`
    )
    .join('\n    ');
  return `<svg class="pattern" width="${W}" height="${H}" aria-hidden="true">
    <defs><pattern id="dots" width="90" height="156" patternUnits="userSpaceOnUse">
      <circle cx="0" cy="0" r="1" fill="currentColor" opacity="0.05"/>
      <circle cx="90" cy="0" r="1" fill="currentColor" opacity="0.05"/>
      <circle cx="45" cy="78" r="1" fill="currentColor" opacity="0.05"/>
    </pattern></defs>
    <rect width="${W}" height="${H}" fill="url(#dots)"/>
    <line x1="60" y1="0" x2="60" y2="${H}" stroke="currentColor" stroke-width="1" opacity="0.08"/>
    <line x1="${W - 60}" y1="0" x2="${W - 60}" y2="${H}" stroke="currentColor" stroke-width="1" opacity="0.08"/>
    ${ticks}
  </svg>`;
}

// Progress dots reuse the medallion's own ring-vs-fill language: an inactive
// slide is a hollow gold ring, the current slide is a solid gold dot with a
// wider ring around it — a miniature echo of the badge, not a separate motif.
function instrumentProgress(b, n, total) {
  let out = '';
  for (let i = 1; i <= total; i++) {
    out +=
      i === n
        ? `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3" fill="${b.color_gold}"/><circle cx="12" cy="12" r="6" fill="none" stroke="${b.color_gold}" stroke-width="1"/></svg>`
        : `<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3" fill="none" stroke="${b.color_gold}" stroke-width="1.5" opacity="0.35"/></svg>`;
  }
  return `<div class="progress" aria-label="${n} / ${total}">${out}</div>`;
}

// "Double Tick" motif — a line-art reinterpretation of chat bubbles and
// read-receipt double-ticks for the Sarcastic/Memes template. The joke is a
// design pun, not a punchline graphic: the medallion's focal icon is a
// read-receipt mark ("you already know this, right?" = you've already
// "seen" it), and progress dots quietly read as seen-vs-unread bubbles.
// Deliberately built from zero chart/candlestick/growth shapes (that lesson
// was already learned designing the Informative template's motif) and zero
// checkmark/certification/notification-badge shapes — a design-workflow
// judge panel flagged both as compliance-adjacent (implied verification,
// implied urgency) and those exact devices were dropped before this shipped:
// the medallion carries no notification dot, and the "tick" glyph is two
// independent parallel dashes with no bend, so it can never read as a ✓.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Rounded square with a small triangular tail on one corner — an abstract
// chat-bubble silhouette, never literally drawn as app UI.
function bubbleGlyph(cx, cy, size, rotation, stroke, strokeWidth, opacity, filled) {
  const r = size / 2;
  const corner = size * 0.18;
  const tail = size * 0.22;
  const fillAttr = filled ? stroke : 'none';
  return `<g transform="rotate(${rotation.toFixed(1)} ${cx.toFixed(1)} ${cy.toFixed(1)})" opacity="${opacity}">
    <rect x="${(cx - r).toFixed(1)}" y="${(cy - r).toFixed(1)}" width="${size.toFixed(1)}" height="${size.toFixed(1)}" rx="${corner.toFixed(1)}" fill="${fillAttr}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}"/>
    <path d="M ${(cx + r - tail * 0.7).toFixed(1)} ${(cy + r).toFixed(1)} L ${(cx + r + tail * 0.5).toFixed(1)} ${(cy + r + tail * 0.6).toFixed(1)} L ${(cx + r).toFixed(1)} ${(cy + r - tail * 0.2).toFixed(1)}" fill="${fillAttr}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}" stroke-linecap="round" stroke-linejoin="round"/>
  </g>`;
}

// Two short parallel diagonal dashes, offset — a read-receipt "tick" mark
// with no bend anywhere, so it never converges into a checkmark silhouette.
function tickGlyph(cx, cy, size, rotation, stroke, strokeWidth, opacity) {
  const dx = size * 0.22;
  const dy = size * 0.3;
  const gap = size * 0.3;
  return `<g transform="rotate(${rotation.toFixed(1)} ${cx.toFixed(1)} ${cy.toFixed(1)})" opacity="${opacity}">
    <line x1="${(cx - gap / 2 - dx / 2).toFixed(1)}" y1="${(cy - dy / 2).toFixed(1)}" x2="${(cx - gap / 2 + dx / 2).toFixed(1)}" y2="${(cy + dy / 2).toFixed(1)}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}" stroke-linecap="round"/>
    <line x1="${(cx + gap / 2 - dx / 2).toFixed(1)}" y1="${(cy - dy / 2).toFixed(1)}" x2="${(cx + gap / 2 + dx / 2).toFixed(1)}" y2="${(cy + dy / 2).toFixed(1)}" stroke="${stroke}" stroke-width="${strokeWidth.toFixed(2)}" stroke-linecap="round"/>
  </g>`;
}

function dotsGlyph(cx, cy, size, stroke, opacity) {
  const r = size * 0.09;
  const gap = size * 0.32;
  let out = '';
  for (let i = -1; i <= 1; i++) {
    out += `<circle cx="${(cx + i * gap).toFixed(1)}" cy="${cy.toFixed(1)}" r="${r.toFixed(1)}" fill="${stroke}" opacity="${opacity}"/>`;
  }
  return out;
}

// Badge: two concentric notch-bubble squares (the inner one rotated ~9°, a
// quiet "stack of overlapping bubbles" cue), with the tick glyph centered as
// the bold focal icon — literally a read-receipt mark as the emblem. No
// notification dot (dropped: an unread-count badge is an urgency device the
// brand voice rules forbid, regardless of color).
function memeMedallion(b, size) {
  const c = size / 2;
  const outerSize = size * 0.86;
  const innerSize = outerSize * 0.78;
  let svg = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true">`;
  svg += bubbleGlyph(c, c, outerSize, 0, b.color_gold, size * 0.0065, 1, false);
  svg += bubbleGlyph(c, c, innerSize, 9, b.color_gold, size * 0.0045, 0.6, false);
  svg += tickGlyph(c, c, size * 0.42, 0, b.color_gold, size * 0.03, 1);
  svg += `</svg>`;
  return svg;
}

function memeMark(b) {
  if (b.logo_url) {
    return `<img class="logo-img" src="${esc(b.logo_url)}" alt="">`;
  }
  return `<svg class="mark" viewBox="0 0 48 48" aria-hidden="true">${bubbleGlyph(24, 24, 34, 0, b.color_gold, 2.4, 1, false)}${tickGlyph(24, 24, 16, 0, b.color_gold, 2.6, 1)}</svg>`;
}

// Full-bleed scatter of 3 glyphs from one shared shape family (bubbles,
// ticks, a typing-dots triad) — deterministically seeded so every render is
// identical, not visual noise. A central zone stays clear of glyphs, and
// every instance sits at 6-8% opacity, so the pattern never competes with
// headline/body text even where it does cross behind it.
function memeBackdrop(b) {
  const rand = mulberry32(20260917);
  // Text can plausibly sit anywhere in this zone across all 3 slide types
  // (cover's bottom-anchored title, content's/cta's centered blocks) — kept
  // fully clear of bubble/tick glyphs, not just biased, after an earlier
  // render showed a "biased density" approach still crowded real text.
  const safe = { x0: 120, y0: 230, x1: 960, y1: 1150 };
  const glyphs = [];
  let guard = 0;
  while (glyphs.length < 16 && guard++ < 500) {
    const x = 40 + rand() * (W - 80);
    const y = 40 + rand() * (H - 80);
    if (x > safe.x0 && x < safe.x1 && y > safe.y0 && y < safe.y1) continue;
    const size = 26 + rand() * 30;
    const rotation = (rand() - 0.5) * 40;
    const roll = rand();
    const kind = roll < 0.5 ? 'bubble' : roll < 0.8 ? 'tick' : 'dots';
    const isGold = rand() < 0.3;
    const stroke = isGold ? b.color_gold : 'currentColor';
    const opacity = isGold ? 0.05 : 0.06;
    glyphs.push({ x, y, size, rotation, kind, stroke, opacity });
  }
  // The typing-dots triad is small enough (like True Bearing's dot lattice)
  // to read as ambient texture rather than a shape, so it alone is allowed
  // to scatter across the full canvas, still at very low opacity.
  const dotCount = 10;
  for (let i = 0; i < dotCount; i++) {
    glyphs.push({
      x: 40 + rand() * (W - 80),
      y: 40 + rand() * (H - 80),
      size: 14 + rand() * 10,
      rotation: 0,
      kind: 'dots',
      stroke: 'currentColor',
      opacity: 0.05,
    });
  }
  const body = glyphs
    .map((g) => {
      const sw = Math.max(1, g.size * 0.05);
      if (g.kind === 'bubble') return bubbleGlyph(g.x, g.y, g.size, g.rotation, g.stroke, sw, g.opacity, false);
      if (g.kind === 'tick') return tickGlyph(g.x, g.y, g.size, g.rotation, g.stroke, sw, g.opacity);
      return dotsGlyph(g.x, g.y, g.size * 0.6, g.stroke, g.opacity);
    })
    .join('');
  return `<svg class="pattern" width="${W}" height="${H}" aria-hidden="true">${body}</svg>`;
}

// Progress dots stay on the same bubble shape as the rest of the system:
// inactive is a hollow outline, passed is a dim filled bubble ("delivered
// but already scrolled past"), active is a bold gold filled bubble.
function memeProgress(b, n, total) {
  let out = '';
  for (let i = 1; i <= total; i++) {
    if (i === n) {
      out += `<svg viewBox="0 0 24 24" aria-hidden="true">${bubbleGlyph(12, 12, 15, 0, b.color_gold, 1, 1, true)}</svg>`;
    } else if (i < n) {
      out += `<svg viewBox="0 0 24 24" aria-hidden="true">${bubbleGlyph(12, 12, 11, 0, b.color_muted_light, 1, 0.55, true)}</svg>`;
    } else {
      out += `<svg viewBox="0 0 24 24" aria-hidden="true">${bubbleGlyph(12, 12, 11, 0, b.color_muted_light, 1.3, 0.35, false)}</svg>`;
    }
  }
  return `<div class="progress" aria-label="${n} / ${total}">${out}</div>`;
}

// ---------- motif registry ----------
// Each pack supplies medallion/backdrop/progress/mark. cssVars lets a motif
// nudge shared typographic feel (e.g. a bolder headline weight) without any
// of the 3 slide-layout functions changing — empty by default.
const MOTIFS = {
  instrument: {
    medallion: instrumentMedallion,
    backdrop: instrumentBackdrop,
    progress: instrumentProgress,
    mark: instrumentMark,
    cssVars: {},
  },
  meme: {
    medallion: memeMedallion,
    backdrop: memeBackdrop,
    progress: memeProgress,
    mark: memeMark,
    cssVars: {},
  },
};

function resolveMotif(b) {
  return MOTIFS[b.motif_key] || MOTIFS.instrument;
}

// Shrinks any [data-fit] element until its text fits its max-height.
// Adds body.ready when done → can be used with Browser Run's waitForSelector.
const FIT_SCRIPT = `
(function () {
  var done = false;
  function fit() {
    if (done) return; done = true;
    document.querySelectorAll('[data-fit]').forEach(function (el) {
      var cs = getComputedStyle(el);
      var min = parseFloat(el.dataset.min) || 28;
      var maxH = parseFloat(cs.maxHeight);
      var size = parseFloat(cs.fontSize);
      var guard = 0;
      el.style.maxHeight = 'none';
      // offsetHeight = height of the line boxes (ignores glyph ink overflow)
      while (el.offsetHeight > maxH + 1 && size > min && guard++ < 80) {
        size -= 2;
        el.style.fontSize = size + 'px';
      }
    });
    document.body.classList.add('ready');
  }
  var b = document.body.dataset;
  var sample = document.body.innerText;
  if (document.fonts && document.fonts.load) {
    Promise.all([
      document.fonts.load('600 80px "' + b.display + '"', sample),
      document.fonts.load('400 40px "' + b.body + '"', sample),
      document.fonts.load('600 40px "' + b.body + '"', sample)
    ]).then(function () { return document.fonts.ready; }).then(fit, fit);
  }
  setTimeout(fit, 5000);
})();`;

